using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public interface IPaymentStrategy
{
    string Method { get; }
    Task<bool> ChargeAsync(decimal amount);
}

public class CreditCardStrategy : IPaymentStrategy
{
    public string Method => "CREDIT_CARD";
    public Task<bool> ChargeAsync(decimal amount)
    {
        Console.WriteLine($"[CreditCard] Berhasil mendebit Rp {amount:N0}");
        return Task.FromResult(true);
    }
}

public class QrisStrategy : IPaymentStrategy
{
    public string Method => "QRIS";
    public Task<bool> ChargeAsync(decimal amount)
    {
        Console.WriteLine($"[QRIS] QR Code dipindai. Berhasil membayar Rp {amount:N0}");
        return Task.FromResult(true);
    }
}

public class PaymentGateway
{
    private readonly Dictionary<string, IPaymentStrategy> _strategies = new();

    public void RegisterStrategy(IPaymentStrategy strategy)
    {
        _strategies[strategy.Method] = strategy;
    }

    public async Task ProcessAsync(string method, decimal amount)
    {
        if (!_strategies.TryGetValue(method, out var strategy))
        {
            throw new NotSupportedException($"Metode {method} tidak didukung!");
        }

        await strategy.ChargeAsync(amount);
    }
}

public class Program
{
    public static async Task Main()
    {
        var gateway = new PaymentGateway();
        gateway.RegisterStrategy(new CreditCardStrategy());
        gateway.RegisterStrategy(new QrisStrategy());

        await gateway.ProcessAsync("CREDIT_CARD", 150_000);
        await gateway.ProcessAsync("QRIS", 75_000);
    }
}
